(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-465":{scenario:{company:"Thiên Phúc Electronics",supervisor:{name:"Bùi Thị Thanh Tâm",role:{vi:"Trưởng nhóm Quan hệ Lao động",en:"Employee Relations Lead"}},ref_code:"ER-0815",title:{vi:"Kỷ luật đúng luật. Đo gắn kết đúng cách. Đối thoại thay đối đầu.",en:"Lawful discipline. Accurate engagement. Dialogue over conflict."},brief:{vi:"Đây là tình huống đào tạo. Bạn hoàn thiện báo cáo quan hệ lao động ER-0815 của nhà máy 500 người. Ca thứ nhất: công nhân Hòa đi muộn 3 lần, là vi phạm đầu tiên trong năm, quản đốc đề xuất trừ 500.000 đồng lương. Ca thứ hai: khảo sát eNPS có 400 người trả lời, gồm 168 người chấm 9-10, 142 người chấm 7-8 và 90 người chấm 0-6. Đối chiếu báo cáo nháp với hồ sơ đã duyệt, sửa hình thức xử lý vi phạm và điểm eNPS, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are finishing employee relations report ER-0815 for a 500-person plant. Case one: worker Hoa was late 3 times, his first offence this year, and the foreman proposes docking VND 500,000 from his pay. Case two: the eNPS survey had 400 respondents, with 168 scoring 9-10, 142 scoring 7-8 and 90 scoring 0-6. Compare the draft report with the approved file, correct the disciplinary measure and the eNPS score, then write an evidence-based report."},reference_title:{vi:"Nội quy lao động & kết quả khảo sát đã duyệt · ER-0815",en:"Approved work rules & survey results · ER-0815"},fields:[{id:"DISCIPLINE",label:{vi:"Hình thức xử lý vi phạm của công nhân Hòa",en:"Disciplinary measure for worker Hoa"},initial:"FINE",expected:"REPRIMAND",choices:["FINE","REPRIMAND","DISMISSAL"],reference:"Nội quy lao động đã đăng ký",hint:{vi:"Pháp luật cấm phạt tiền, cắt lương thay cho kỷ luật; vi phạm lần đầu mức nhẹ áp dụng khiển trách theo nội quy.",en:"The law bans fines or pay cuts in place of discipline; a minor first offence carries a reprimand under the work rules."}},{id:"ENPS",label:{vi:"Điểm eNPS của nhà máy",en:"Plant eNPS score"},initial:"15.6",expected:"19.5",reference:"Kết quả khảo sát gắn kết đã chốt",ref_value:{vi:"400 người trả lời / 500 nhân viên; 9-10 điểm: 168; 7-8 điểm: 142; 0-6 điểm: 90",en:"400 respondents / 500 employees; scores 9-10: 168; 7-8: 142; 0-6: 90"},hint:{vi:"Bản nháp chia cho tổng số nhân viên; eNPS chỉ tính trên số người trả lời khảo sát.",en:"The draft divided by total headcount; eNPS is computed on survey respondents only."}}],sop32:{vi:"eNPS = (số người chấm 9-10 - số người chấm 0-6) / tổng số người trả lời x 100, làm tròn 1 chữ số thập phân; nhóm 7-8 điểm chỉ tính ở mẫu số.",en:"eNPS = (respondents scoring 9-10 - respondents scoring 0-6) / total respondents x 100, rounded to 1 decimal place; the 7-8 group counts only in the denominator."},context:{label:"HỒ SƠ QHLĐ / ER-0815",metrics:[{label:{vi:"Tổng nhân viên",en:"Total employees"},value:"500"},{label:{vi:"Người trả lời khảo sát",en:"Survey respondents"},value:"400"},{label:{vi:"Đề xuất của quản đốc",en:"Foreman's proposal"},value:"-500,000 VND"}]},crisis:{vi:"Giám đốc nhà máy nhắn: “Hôm qua tổ 3 ngừng việc 2 giờ đòi tăng tiền ăn ca. Lập danh sách mấy người cầm đầu, tháng này cho nghỉ hết để răn đe, đừng tổ chức đối thoại gì cả.”",en:"The plant director messages you: “Team 3 stopped work for 2 hours yesterday demanding a higher meal allowance. List the ringleaders and let them all go this month as a warning, and don't hold any dialogue.”"},options:{safe:{vi:"Không lập danh sách trù dập; báo Trưởng nhóm Quan hệ Lao động và Giám đốc Nhân sự, đề xuất đối thoại ngay với đại diện người lao động, công đoàn, ghi nhận kiến nghị và xử lý đúng trình tự pháp luật.",en:"Do not draw up a retaliation list; inform the ER Lead and HR Director, propose immediate dialogue with worker representatives and the union, record the demands and follow the legal process."},shortcut:{vi:"Lập danh sách người cầm đầu và chấm dứt hợp đồng ngay trong tháng như yêu cầu.",en:"List the ringleaders and terminate their contracts this month as instructed."},wait:{vi:"Im lặng chờ công nhân tự trở lại làm việc và không báo cáo ai.",en:"Stay quiet, wait for the workers to return and report nothing."}},questions:{vi:["Vì sao ca của công nhân Hòa phải xử lý REPRIMAND thay vì trừ lương, và vì sao eNPS đúng là 19.5? Trình bày căn cứ và phép tính.","Sa thải người lao động vì ngừng việc đòi quyền lợi gây rủi ro gì? Bạn tổ chức đối thoại theo trình tự nào?"],en:["Why must worker Hoa's case be a REPRIMAND rather than a pay cut, and why is eNPS 19.5? Give your basis and calculation.","What risks arise from dismissing workers who stopped work over a grievance? In what sequence would you run the dialogue?"]},hints:{vi:["So đề xuất của quản đốc với nội quy lao động và danh mục hình thức kỷ luật hợp pháp.","Lấy nhóm 9-10 trừ nhóm 0-6, rồi chia cho số người trả lời theo SOP mục 3.2.","Đọc lại SOP mục 4.2: bất đồng phải được giải quyết bằng đối thoại; không trù dập người lao động vì kiến nghị quyền lợi."],en:["Compare the foreman's proposal with the work rules and the list of lawful disciplinary measures.","Subtract the 0-6 group from the 9-10 group, then divide by respondents as in SOP 3.2.","Re-read SOP 4.2: disputes are settled through dialogue; never retaliate against workers for raising grievances."]}},learning:{summary:{vi:"Chuyên viên quan hệ lao động và gắn kết nhân viên xây dựng môi trường làm việc hài hòa, ổn định: tổ chức đối thoại, giải quyết khiếu nại, tư vấn kỷ luật đúng luật, phối hợp công đoàn và đo lường, cải thiện mức độ gắn kết. Nghề là cầu nối giữa người lao động và ban lãnh đạo, đòi hỏi biết lắng nghe, đàm phán, nắm vững pháp luật lao động và công tâm.",en:"An employee relations and engagement specialist builds a harmonious and stable workplace: running dialogue, resolving grievances, advising on lawful discipline, working with the union and measuring and improving engagement. The role bridges workers and management and requires listening, negotiation, a firm grasp of labour law and impartiality."},responsibilities:{vi:["Tiếp nhận, phân loại, điều tra và phản hồi khiếu nại, kiến nghị của người lao động.","Tư vấn quản lý xử lý kỷ luật lao động đúng nội quy, trình tự và thời hiệu.","Tổ chức đối thoại định kỳ, đột xuất và phối hợp với công đoàn cơ sở.","Thiết kế, triển khai khảo sát gắn kết, phân tích kết quả và lập kế hoạch hành động.","Theo dõi dấu hiệu tranh chấp, ngừng việc tập thể và phối hợp xử lý sớm."],en:["Receive, classify, investigate and answer employee grievances and suggestions.","Advise managers on discipline that follows the work rules, procedure and time limits.","Run periodic and ad hoc dialogue and work with the workplace union.","Design and run engagement surveys, analyse results and build action plans.","Watch for dispute and work stoppage signals and act early."]},competencies:[{name:{vi:"Lắng nghe & hòa giải",en:"Listening & mediation"},desc:{vi:"Tạo không gian an toàn để người lao động trình bày và tìm giải pháp hai bên cùng chấp nhận.",en:"Create a safe space for workers to speak and find solutions both sides accept."}},{name:{vi:"Điều tra công tâm",en:"Fair investigation"},desc:{vi:"Thu thập chứng cứ, lời khai, bảo mật người phản ánh và kết luận khách quan.",en:"Gather evidence and statements, protect complainants and reach objective findings."}},{name:{vi:"Pháp luật lao động",en:"Labour law"},desc:{vi:"Nắm nội quy, kỷ luật, thời hiệu, đối thoại, thương lượng tập thể và giải quyết tranh chấp.",en:"Know work rules, discipline, time limits, dialogue, collective bargaining and dispute resolution."}},{name:{vi:"Đo lường gắn kết",en:"Engagement measurement"},desc:{vi:"Thiết kế câu hỏi, tính eNPS, chỉ số gắn kết và phân tích theo từng nhóm.",en:"Design questions, compute eNPS and engagement indices and analyse by group."}},{name:{vi:"Đàm phán & truyền thông nội bộ",en:"Negotiation & internal communication"},desc:{vi:"Truyền đạt quyết định minh bạch và thương lượng với đại diện người lao động.",en:"Communicate decisions transparently and negotiate with worker representatives."}}],knowledge:{vi:["Bộ luật Lao động số 45/2019/QH14: nội quy lao động, trình tự xử lý kỷ luật (Điều 122) và các hình thức kỷ luật (Điều 124).","Cấm phạt tiền, cắt lương thay việc xử lý kỷ luật lao động (Điều 127 Bộ luật Lao động 2019).","Đối thoại tại nơi làm việc định kỳ ít nhất một lần mỗi năm và khi có yêu cầu; hướng dẫn tại Nghị định 145/2020/NĐ-CP.","Luật Công đoàn và quyền thành lập, gia nhập, hoạt động của tổ chức đại diện người lao động.","Trình tự giải quyết tranh chấp lao động qua hòa giải viên lao động, Hội đồng trọng tài lao động hoặc Tòa án.","Chỉ số eNPS và khung khảo sát gắn kết nhân viên."],en:["Labour Code No. 45/2019/QH14: work rules, disciplinary procedure (Article 122) and disciplinary measures (Article 124).","Fines and pay cuts in place of discipline are prohibited (Article 127 of the 2019 Labour Code).","Workplace dialogue at least once a year and on request, guided by Decree 145/2020/ND-CP.","The Trade Union Law and the right to form, join and run employee representative organisations.","Labour dispute resolution through labour mediators, the labour arbitration council or the courts.","The eNPS metric and employee engagement survey frameworks."]},tools:["Hệ thống tiếp nhận khiếu nại, đường dây nóng","Nền tảng khảo sát gắn kết ẩn danh","Hồ sơ điện tử vụ việc quan hệ lao động","Bảng tính phân tích gắn kết theo nhóm","Bảng tin và kênh truyền thông nội bộ"],kpis:{vi:["Thời gian phản hồi và đóng khiếu nại theo cam kết.","Số vụ tranh chấp, ngừng việc tập thể và thời gian giải quyết.","Điểm eNPS và tỷ lệ tham gia khảo sát.","Tỷ lệ quyết định kỷ luật đúng trình tự, không bị hủy khi bị khiếu nại."],en:["Grievance response and closure time against commitments.","Number of disputes and work stoppages and time to resolve them.","eNPS score and survey participation rate.","Share of disciplinary decisions made properly and upheld on appeal."]},day:[{time:"08:00",vi:"Đi xưởng đầu ca, lắng nghe tổ trưởng và công nhân về vướng mắc.",en:"Walk the floor at shift start and listen to team leaders and workers."},{time:"09:30",vi:"Xử lý ba khiếu nại mới, phỏng vấn các bên liên quan.",en:"Handle three new grievances and interview the parties."},{time:"13:30",vi:"Họp với quản đốc, tư vấn hồ sơ kỷ luật theo nội quy.",en:"Meet a foreman to advise on a disciplinary file under the work rules."},{time:"15:00",vi:"Họp chuẩn bị đối thoại với công đoàn cơ sở.",en:"Prepare the upcoming dialogue with the workplace union."},{time:"16:30",vi:"Phân tích kết quả khảo sát gắn kết và soạn kế hoạch hành động.",en:"Analyse engagement survey results and draft the action plan."}],mistakes:{vi:["Phạt tiền, trừ lương thay cho kỷ luật hoặc kỷ luật hành vi không có trong nội quy.","Tính eNPS trên tổng nhân viên thay vì người trả lời, hoặc tính nhóm 7-8 điểm là người ủng hộ.","Né tránh đối thoại, trù dập người kiến nghị khiến mâu thuẫn bùng phát thành ngừng việc tập thể."],en:["Fining or docking pay instead of disciplining, or disciplining conduct not in the work rules.","Computing eNPS on headcount instead of respondents, or counting 7-8 scores as promoters.","Avoiding dialogue and retaliating against complainants, so tensions erupt into work stoppages."]},career:[{vi:"Chuyên viên quan hệ lao động",en:"Employee relations officer"},{vi:"Chuyên viên gắn kết nhân viên",en:"Engagement specialist"},{vi:"Trưởng nhóm quan hệ lao động",en:"Employee relations lead"},{vi:"Quản lý quan hệ lao động & văn hóa",en:"Employee relations & culture manager"}],glossary:[{term:"eNPS",vi:"Chỉ số giới thiệu nơi làm việc, bằng % người ủng hộ (9-10) trừ % người phản đối (0-6).",en:"Employee Net Promoter Score: % promoters (9-10) minus % detractors (0-6)."},{term:"Work rules",vi:"Nội quy lao động bằng văn bản về kỷ luật, trách nhiệm vật chất; doanh nghiệp từ 10 lao động phải đăng ký.",en:"Written rules on discipline and material liability; employers with 10 or more workers must register them."},{term:"Reprimand",vi:"Khiển trách, hình thức kỷ luật nhẹ nhất trong các hình thức theo Bộ luật Lao động.",en:"The mildest of the disciplinary measures set by the Labour Code."},{term:"Collective bargaining",vi:"Thương lượng giữa đại diện người lao động và người sử dụng lao động về điều kiện lao động.",en:"Negotiation between worker representatives and the employer on working conditions."},{term:"Limitation period",vi:"Thời hiệu xử lý kỷ luật: 6 tháng từ ngày vi phạm, 12 tháng nếu liên quan tài chính, tài sản, bí mật kinh doanh.",en:"Time limit for discipline: 6 months from the offence, 12 months for finance, assets or trade secrets."}],quiz:[{q:{vi:"Có 250 người trả lời: 100 người chấm 9-10, 90 người chấm 7-8, 60 người chấm 0-6. eNPS là bao nhiêu?",en:"There are 250 respondents: 100 score 9-10, 90 score 7-8 and 60 score 0-6. What is the eNPS?"},options:{vi:["40","16","76","-16"],en:["40","16","76","-16"]},answer:1,explain:{vi:"(100 - 60) / 250 x 100 = 16; nhóm 7-8 điểm chỉ nằm ở mẫu số.",en:"(100 - 60) / 250 x 100 = 16; the 7-8 group sits only in the denominator."}},{q:{vi:"Hành vi nào bị cấm khi xử lý kỷ luật lao động?",en:"Which practice is prohibited in labour discipline?"},options:{vi:["Khiển trách bằng văn bản","Mời công đoàn tham dự","Cho người lao động tự bào chữa","Phạt tiền, cắt lương thay kỷ luật"],en:["A written reprimand","Inviting the union","Letting the worker defend himself","Fining or cutting pay instead of discipline"]},answer:3,explain:{vi:"Điều 127 Bộ luật Lao động 2019 cấm phạt tiền, cắt lương thay việc xử lý kỷ luật.",en:"Article 127 of the 2019 Labour Code bans fines and pay cuts in place of discipline."}},{q:{vi:"Công nhân ngừng việc đòi tăng tiền ăn ca, giám đốc muốn sa thải người cầm đầu. Bạn làm gì?",en:"Workers stop work over the meal allowance and the director wants the leaders fired. What do you do?"},options:{vi:["Đề xuất đối thoại ngay, báo Giám đốc Nhân sự và xử lý đúng trình tự","Lập danh sách và cho nghỉ việc","Cắt thưởng cả tổ","Không làm gì"],en:["Propose immediate dialogue, inform the HR Director and follow due process","List them and dismiss them","Cut the whole team's bonus","Do nothing"]},answer:0,explain:{vi:"Đối thoại kịp thời giúp hạ nhiệt; trù dập người kiến nghị vừa trái luật vừa làm xung đột lan rộng.",en:"Prompt dialogue de-escalates; retaliation is unlawful and spreads the conflict."}},{q:{vi:"Thời hiệu xử lý kỷ luật lao động thông thường là bao lâu?",en:"What is the usual time limit for labour discipline?"},options:{vi:["1 tháng","3 tháng","6 tháng kể từ ngày vi phạm","24 tháng"],en:["1 month","3 months","6 months from the offence","24 months"]},answer:2,explain:{vi:"Thời hiệu là 6 tháng; 12 tháng với vi phạm liên quan trực tiếp tài chính, tài sản, bí mật công nghệ, kinh doanh.",en:"The limit is 6 months, or 12 months for offences tied directly to finance, assets or technology and trade secrets."}}],tools_en:["Grievance intake and hotline system","Anonymous engagement survey platform","Electronic employee relations case files","Team engagement analysis spreadsheet","Notice boards and internal comms channels"]}}})})(window.KKR);
